from .repository import contact_exists, put_contact

_ROW_FIELDS = frozenset({"email", "name"})

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(row):
    if not isinstance(row, dict):
        raise ValueError("import row must be an object")
    fields = set(row)
    if fields != _ROW_FIELDS:
        missing = sorted(_ROW_FIELDS - fields)
        unknown = sorted(str(field) for field in fields - _ROW_FIELDS)
        raise ValueError(f"import row must have exactly email and name (missing={missing}, unknown={unknown})")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("email and name must be strings")
    email = email.strip().lower()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError("email must contain exactly one @")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError("email must have nonempty sides around @")
    if any(ch.isspace() for ch in email):
        raise ValueError("email must not contain whitespace")
    if not name:
        raise ValueError("name must not be empty")
    return email, name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    normalized = []
    seen = set()
    for row in rows:
        email, name = _normalize_row(row)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email}")
        seen.add(email)
        normalized.append((email, name))
    inserted = 0
    updated = 0
    with connection:
        for email, name in normalized:
            if contact_exists(connection, email):
                updated += 1
            else:
                inserted += 1
            put_contact(connection, email, name)
    return {"inserted": inserted, "updated": updated}
EOF
